const $=s=>document.querySelector(s); let products=[],cart=JSON.parse(localStorage.getItem('feili-cart')||'[]'),currency=localStorage.getItem('feili-currency')||'USD';
const rates={USD:1,HKD:7.8,EUR:.92,GBP:.79,CAD:1.36,AUD:1.52}; const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(n*rates[currency]);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem('feili-cart',JSON.stringify(cart));render()}
function render(){ $('#count').textContent=cart.reduce((a,c)=>a+c.qty,0); $('#productGrid').innerHTML=products.map((p,i)=>`<article><img class="product-image" src="${p.image}" alt="${escapeHTML(p.title)}" loading="lazy"><div class="product-info"><div><h3>${escapeHTML(p.title)}</h3><p>${money(p.price)}</p></div><button aria-label="Add ${escapeHTML(p.title)} to bag" data-add="${i}">+</button></div></article>`).join(''); const sum=cart.reduce((s,c)=>s+c.price*c.qty,0); $('#cartItems').innerHTML=cart.length?cart.map((c,i)=>`<div class="cart-item"><img src="${c.image}" alt=""><div><strong>${escapeHTML(c.title)}</strong><p>${money(c.price)} × ${c.qty}</p><button data-remove="${i}">Remove</button></div></div>`).join(''):'<p>Your bag is currently empty.</p>'; $('#subtotal').textContent=money(sum);$('#shipping').textContent=money(cart.length?15:0);$('#total').textContent=money(sum+(cart.length?15:0)); }
function showCart(open){$('#drawer').hidden=!open;$('#overlay').hidden=!open} function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
const company='<p>HONG KONG FEILI TECH CO., LIMITED<br>FLAT/RM 03 24/F<br>HO KING COMM CTR<br>2-16 FA YUEN STREET<br>MONG KOK KL<br>Phone: <a href="tel:+852528546981">+852 528546981</a></p>';
const pages={contact:`<h2>Contact Us</h2><p>For questions about our products or an order, please contact us by telephone.</p>${company}`,shipping:`<h2>Shipping & Delivery</h2><p>Standard shipping is a flat <strong>$15.00 USD per order</strong>, regardless of order value. The shipping charge is shown in your bag and in the checkout summary. Prices in other currencies are indicative conversions.</p><h3>Delivery destinations</h3><p>Available destinations are shown at checkout. We do not ship to destinations subject to applicable trade restrictions, including Cuba, Iran, North Korea, Crimea and the so-called Donetsk and Luhansk regions of Ukraine. Orders may also be restricted after sanctions screening. Delivery timing, taxes and import charges depend on the destination and will be confirmed before payment.</p><h3>Questions</h3>${company}`,returns:`<h2>Returns & Exchange</h2><p>Please contact us within 30 days of receiving your order if you wish to request a return or exchange. Items should be unused and in their original packaging. Contact us before sending any item back so we can provide return instructions and confirm eligibility.</p><p>Refunds, when approved, are returned to the original payment method. Return shipping costs and any exceptions will be explained before you return the item. This policy does not limit rights provided by applicable law.</p>${company}`,privacy:`<h2>Privacy Policy</h2><p>We use information you provide, such as contact and delivery details, to respond to enquiries and fulfill orders. Payment details are handled by the payment provider when a payment service is connected. We may use service providers to operate the store and deliver orders.</p><p>We retain information only as needed for business and legal purposes and use reasonable safeguards. You may contact us to ask about access, correction or deletion of your personal information, subject to applicable law.</p>${company}`,terms:`<h2>Terms of Service</h2><p>This website is operated by HONG KONG FEILI TECH CO., LIMITED. By using the site, you agree to use it lawfully and provide accurate information when placing an order. Product availability and prices may change; an order is subject to acceptance and availability.</p><p>Shipping charges are described in Shipping & Delivery. Applicable taxes and any import charges will be disclosed before payment where required. Please review the return policy before purchasing.</p><p>These terms are governed by applicable laws of the United States and the relevant state, subject to mandatory consumer protections applicable to you. Nothing in these terms limits rights that cannot lawfully be excluded.</p>${company}`};
$('#currency').value=currency;$('#currency').onchange=e=>{currency=e.target.value;localStorage.setItem('feili-currency',currency);render()};document.addEventListener('click',e=>{let add=e.target.closest('[data-add]');if(add){let p=products[+add.dataset.add],item=cart.find(c=>c.title===p.title);item?item.qty++:cart.push({...p,qty:1});save();showCart(true)} let remove=e.target.closest('[data-remove]');if(remove){cart.splice(+remove.dataset.remove,1);save()}let page=e.target.closest('[data-page]');if(page)modal(pages[page.dataset.page]);});$('#cartBtn').onclick=()=>showCart(true);$('.close').onclick=()=>showCart(false);$('#overlay').onclick=()=>showCart(false);$('.modal-close').onclick=()=>$('#modal').close();$('.mobile-menu').onclick=()=>modal('<h2>Explore</h2><p><a href="#collections" onclick="document.querySelector(\'dialog\').close()">Collections</a></p><p><a href="#products" onclick="document.querySelector(\'dialog\').close()">Shop lighting</a></p><p><a href="#about" onclick="document.querySelector(\'dialog\').close()">About</a></p>');
$('#searchBtn').onclick=()=>{modal('<h2>Search</h2><label for="query">Search our collection</label><input id="query" type="search" placeholder="Search products"><div id="results"></div>');$('#query').oninput=e=>{$('#results').innerHTML=products.filter(p=>p.title.toLowerCase().includes(e.target.value.toLowerCase())).map(p=>`<p>${escapeHTML(p.title)} — ${money(p.price)}</p>`).join('')}};
$('#checkoutBtn').onclick=()=>{if(!cart.length){modal('<h2>Your bag is empty</h2><p>Add a piece to your bag to continue.</p>');return}showCart(false);let total=cart.reduce((s,c)=>s+c.price*c.qty,0)+15;modal(`<h2>Guest checkout</h2><p>Standard shipping: ${money(15)} · Estimated total: <strong>${money(total)}</strong></p><p class="notice">Preview only: payment processing and order submission are not yet connected. No order will be placed.</p><form id="checkout"><label>Email<input type="email" required autocomplete="email"></label><label>Full name<input required autocomplete="name"></label><label>Address<input required autocomplete="street-address"></label><label>City<input required autocomplete="address-level2"></label><label>State / Province<input required autocomplete="address-level1"></label><label>Postal code<input required autocomplete="postal-code"></label><label>Country / region<select required><option value="">Select a destination</option><option>United States</option><option>Canada</option><option>United Kingdom</option><option>Hong Kong SAR</option><option>Australia</option><option>France</option><option>Germany</option><option>Japan</option></select></label><button class="button dark" type="submit">REVIEW ORDER →</button></form>`);$('#checkout').onsubmit=e=>{e.preventDefault();modal('<h2>Checkout preview</h2><p>Payment and order processing have not been connected. Your information has not been submitted.</p><p>Standard shipping: '+money(15)+' · Estimated total: '+money(total)+'</p>')}};
fetch('products.json').then(r=>r.json()).then(data=>{products=data;cart=cart.flatMap(c=>{const p=products.find(p=>p.title===c.title);return p?[{...p,qty:c.qty}]:[]});save()}).catch(()=>{$('#productGrid').textContent='Products are temporarily unavailable.'});
